// black_scholes.hpp: generated by qtrans 0.3.0 from black_scholes.py.
// Edit the Python source and re-run qtrans rather than editing this file.
//
// Black-Scholes-Merton prices and Greeks for European options on a stock paying a
// continuous dividend yield q.
#pragma once

#include <cmath>
#include <algorithm>
#include <stdexcept>
#include <tuple>
#include "qtrans_runtime.hpp"

namespace black_scholes {

inline const long long TRADING_DAYS = 252;

// Declarations (so functions can call each other in any order).
double d1(double S, double K, double r, double sigma, double T, double q = 0.0);
double d2(double S, double K, double r, double sigma, double T, double q = 0.0);
double bs_price(double S, double K, double r, double sigma, double T, double q = 0.0, bool is_call = true);
double delta(double S, double K, double r, double sigma, double T, double q = 0.0, bool is_call = true);
double gamma(double S, double K, double r, double sigma, double T, double q = 0.0);
double vega(double S, double K, double r, double sigma, double T, double q = 0.0);
double theta_per_day(double S, double K, double r, double sigma, double T, double q = 0.0, bool is_call = true);
double rho(double S, double K, double r, double sigma, double T, double q = 0.0, bool is_call = true);
std::tuple<double, double> delta_gamma(double S, double K, double r, double sigma, double T);
double parity_gap(double S, double K, double r, double sigma, double T, double q = 0.0);

/// Standardised moneyness term d1.
inline double d1(double S, double K, double r, double sigma, double T, double q) {
    return (std::log(S / K) + (r - q + 0.5 * (sigma * sigma)) * T) / (sigma * std::sqrt(T));
}

inline double d2(double S, double K, double r, double sigma, double T, double q) {
    return d1(S, K, r, sigma, T, q) - sigma * std::sqrt(T);
}

/// Price of a European call (is_call=True) or put.
inline double bs_price(double S, double K, double r, double sigma, double T, double q, bool is_call) {
    if (S <= 0 || K <= 0) {
        throw std::invalid_argument("spot and strike must be positive");
    }
    if (T <= 0 || sigma <= 0) {
        // expired, or no uncertainty left: discounted intrinsic value of the forward
        double fwd = S * std::exp(-q * std::max(T, 0.0));
        double disc = K * std::exp(-r * std::max(T, 0.0));
        return is_call ? std::max(fwd - disc, 0.0) : std::max(disc - fwd, 0.0);
    }
    double a = d1(S, K, r, sigma, T, q);
    double b = a - sigma * std::sqrt(T);
    if (is_call) {
        return S * std::exp(-q * T) * qt::norm_cdf(a) - K * std::exp(-r * T) * qt::norm_cdf(b);
    }
    return K * std::exp(-r * T) * qt::norm_cdf(-b) - S * std::exp(-q * T) * qt::norm_cdf(-a);
}

inline double delta(double S, double K, double r, double sigma, double T, double q, bool is_call) {
    double a = d1(S, K, r, sigma, T, q);
    if (is_call) {
        return std::exp(-q * T) * qt::norm_cdf(a);
    }
    return -std::exp(-q * T) * qt::norm_cdf(-a);
}

inline double gamma(double S, double K, double r, double sigma, double T, double q) {
    double a = d1(S, K, r, sigma, T, q);
    return std::exp(-q * T) * qt::norm_pdf(a) / (S * sigma * std::sqrt(T));
}

/// Sensitivity to a one-unit change in volatility (not per 1%).
inline double vega(double S, double K, double r, double sigma, double T, double q) {
    double a = d1(S, K, r, sigma, T, q);
    return S * std::exp(-q * T) * qt::norm_pdf(a) * std::sqrt(T);
}

inline double theta_per_day(double S, double K, double r, double sigma, double T, double q, bool is_call) {
    double a = d1(S, K, r, sigma, T, q);
    double b = a - sigma * std::sqrt(T);
    double decay = -S * std::exp(-q * T) * qt::norm_pdf(a) * sigma / (2 * std::sqrt(T));
    double annual = 0.0;
    if (is_call) {
        annual = decay - r * K * std::exp(-r * T) * qt::norm_cdf(b) + q * S * std::exp(-q * T) * qt::norm_cdf(a);
    } else {
        annual = decay + r * K * std::exp(-r * T) * qt::norm_cdf(-b) - q * S * std::exp(-q * T) * qt::norm_cdf(-a);
    }
    return annual / static_cast<double>(TRADING_DAYS);
}

inline double rho(double S, double K, double r, double sigma, double T, double q, bool is_call) {
    double b = d2(S, K, r, sigma, T, q);
    if (is_call) {
        return K * T * std::exp(-r * T) * qt::norm_cdf(b);
    }
    return -K * T * std::exp(-r * T) * qt::norm_cdf(-b);
}

/// Both first- and second-order spot sensitivities of a call in one pass.
inline std::tuple<double, double> delta_gamma(double S, double K, double r, double sigma, double T) {
    double a = d1(S, K, r, sigma, T);
    double n = qt::norm_pdf(a);
    return {qt::norm_cdf(a), n / (S * sigma * std::sqrt(T))};
}

/// Put-call parity error (C - P - (S e^{-qT} - K e^{-rT})) relative to S + K.
///
/// The raw gap is a difference of numbers of size ~S and ~K whose exact value is 0, so it is
/// rounding noise of order (S + K) * 1e-16. Dividing by S + K makes it dimensionless: a
/// consistent pricer gives about 1e-16 whatever the scale of the inputs.
inline double parity_gap(double S, double K, double r, double sigma, double T, double q) {
    double c = bs_price(S, K, r, sigma, T, q, true);
    double p = bs_price(S, K, r, sigma, T, q, false);
    return (c - p - (S * std::exp(-q * T) - K * std::exp(-r * T))) / (S + K);
}

}  // namespace black_scholes
